// ------------------------------------------------------------------
// Art: pixel sprite renderer and mochi cat, plus the flat cat-head record button
// (SPRITES is generated by gen_sprites.py and injected at build time)
// ------------------------------------------------------------------

function Sprite({ rows, px = 4, colors, className, style, label }) {
  const runs = React.useMemo(() => {
    const out = [];
    rows.forEach((r, y) => {
      let x = 0;
      while (x < r.length) {
        const ch = r[x];
        if (ch === ".") { x++; continue; }
        let n = 1;
        while (x + n < r.length && r[x + n] === ch) n++;
        out.push({ x, y, n, ch });
        x += n;
      }
    });
    return out;
  }, [rows]);
  const w = rows[0].length, h = rows.length;
  const pal = colors ? { ...SPRITES.pal, ...colors } : SPRITES.pal;
  return (
    <svg
      viewBox={`0 0 ${w} ${h}`} width={w * px} height={h * px}
      shapeRendering="crispEdges" className={className}
      style={{ maxWidth: "100%", height: "auto", display: "block", ...style }}
      role={label ? "img" : undefined} aria-label={label} aria-hidden={label ? undefined : "true"}
    >
      {runs.map((r, i) => (
        <rect key={i} x={r.x} y={r.y} width={r.n + 0.02} height={1.02} fill={pal[r.ch]} />
      ))}
    </svg>
  );
}

function CatFace({ mood = "idle" }) {
  const [blink, setBlink] = useState(false);
  useEffect(() => {
    if (mood !== "idle") { setBlink(false); return; }
    let off = 0;
    const t = setInterval(() => {
      setBlink(true);
      off = setTimeout(() => setBlink(false), 170);
    }, 3600);
    return () => { clearInterval(t); clearTimeout(off); };
  }, [mood]);
  const key = mood === "idle" && blink ? "blink" : (SPRITES.cat[mood] ? mood : "idle");
  return (
    <Sprite
      rows={SPRITES.cat[key]} px={6} label="Meowchi the mochi cat"
      className={"mc-cat" + (mood === "listen" ? " mc-cat-fast" : "")}
    />
  );
}

// Record button: a soft cat head whose "voice" bars follow the mic while recording.
const REC_HEAD =
  "M22 46 C18 26 22 8 32 6 C42 5 54 16 60 24 C66 22 74 22 80 24 C86 16 98 5 108 6 " +
  "C118 8 122 26 118 46 C130 58 134 72 132 84 C128 108 102 120 70 120 C38 120 12 108 8 84 C6 72 10 58 22 46 Z";
const REC_X = [44, 57, 70, 83, 96];
const REC_IDLE = [8, 15, 22, 15, 8];
const REC_BANDS = [1, 3, 5, 7, 9];

function RecButton({ recording, bars, disabled, onClick }) {
  return (
    <button
      onClick={onClick} disabled={disabled}
      aria-label={recording ? "stop recording" : "record your cat"}
      className={"mc-rec" + (recording ? " mc-rec-on" : "")}
    >
      <svg viewBox="0 0 140 130" width="140" height="130" aria-hidden="true">
        <path d={REC_HEAD} transform="translate(0 8)" className="mc-rec-shade" />
        <g className="mc-rec-top">
          <path d={REC_HEAD} className="mc-rec-face" />
          {recording ? (
            <g className="mc-rec-mark">
              <circle cx="47" cy="60" r="5" />
              <circle cx="93" cy="60" r="5" />
            </g>
          ) : (
            <g className="mc-rec-line">
              <path d="M41 61 Q47 55 53 61" />
              <path d="M87 61 Q93 55 99 61" />
            </g>
          )}
          <ellipse cx="70" cy="70" rx="3.6" ry="2.6" className="mc-rec-mark" />
          {REC_X.map((x, i) => {
            const h = recording ? 7 + Math.min(1, bars[REC_BANDS[i]] || 0) * 24 : REC_IDLE[i];
            return <rect key={i} x={x - 3.5} y={95 - h / 2} width="7" height={h} rx="3.5" className="mc-rec-bar" />;
          })}
        </g>
      </svg>
    </button>
  );
}

function Hearts({ conf }) {
  const n = Math.max(1, Math.min(5, Math.round(conf * 5)));
  return (
    <span className="mc-hearts" role="img" aria-label={`confidence ${n} out of 5`}>
      {[0, 1, 2, 3, 4].map((i) => (
        <Sprite key={i} rows={SPRITES.icons.heart} px={2} colors={{ x: i < n ? "#EC8F9A" : "#E9DACA" }} />
      ))}
    </span>
  );
}

function Meter({ score }) {
  const n = Math.max(1, Math.min(5, Math.round(score * 5)));
  return (
    <span className="mc-meter" role="img" aria-label={`likelihood ${n} out of 5`}>
      {[0, 1, 2, 3, 4].map((i) => <span key={i} className={i < n ? "on" : ""} />)}
    </span>
  );
}

function EqBars() {
  return (
    <span className="mc-eqwrap" aria-hidden="true">
      {[0, 1, 2].map((i) => <span key={i} className="mc-eq" style={{ animationDelay: `${i * 0.14}s` }} />)}
    </span>
  );
}

const SOUND_PALS = {
  pspsps: { bg: "#FBE4E4", bd: "#E9B9BC", fg: "#A9545F" },
  purr: { bg: "#ECE7F3", bd: "#CFC5E0", fg: "#75629C" },
  birds: { bg: "#E3ECF4", bd: "#B9CCDD", fg: "#4C6E90" },
  mouse: { bg: "#F7EDD3", bd: "#E3CF9C", fg: "#886A32" },
  mew: { bg: "#E3EFE9", bd: "#B9D3C7", fg: "#437562" },
  crinkle: { bg: "#F8E6D2", bd: "#E5C29A", fg: "#9A6232" },
};

function SoundCard({ s, active, onToggle }) {
  const pal = SOUND_PALS[s.id];
  const copy = SOUND_COPY[s.id];
  return (
    <button
      onClick={onToggle}
      aria-pressed={active}
      aria-label={(active ? "stop " : "play ") + copy.name}
      className="mc-btn px mc-sound"
      style={{ "--card": pal.bg, "--shade": pal.bd, "--sfg": pal.fg }}
    >
      <span className="mc-sound-top">
        <Sprite rows={SPRITES.icons[s.id]} px={3} colors={{ x: "#E58E9A" }} />
        {active ? <EqBars /> : <span className="mc-play">Play</span>}
      </span>
      <span className="mc-sound-name">{copy.name}</span>
      <span className="mc-sound-tag">{copy.tag}</span>
    </button>
  );
}

